@{
                var unscreenable = false;
                var truncated = false;
                var marker = "\n[...content safety sampled...]\n";
                void addPart(System.Collections.Generic.List<string> list, string value) { var s = value == null ? "" : value.TrimEnd('\r','\n'); if (!String.IsNullOrEmpty(s)) { list.Add(s); } }
                void collectText(JToken token, System.Collections.Generic.List<string> list) {
                    if (token == null) { return; }
                    if (token.Type == JTokenType.String) { addPart(list, token.ToString()); return; }
                    if (token.Type != JTokenType.Array) { unscreenable = true; return; }
                    foreach (var blockToken in (JArray)token) {
                        var block = blockToken as JObject; if (block == null) { unscreenable = true; break; }
                        if (block["type"] == null || block["type"].Type != JTokenType.String) { continue; }
                        var blockType = (string)block["type"];
                        if (blockType == "text" && block["text"] != null && block["text"].Type == JTokenType.String) { addPart(list, (string)block["text"]); }
                        else if (blockType == "document") { var source = block["source"] as JObject; if (source != null && source["type"] != null && source["type"].Type == JTokenType.String && (string)source["type"] == "text" && source["data"] != null && source["data"].Type == JTokenType.String) { addPart(list, (string)source["data"]); } }
                    }
                }
                string sample(string value, int budget) {
                    var s = value == null ? "" : value;
                    if (budget < 1) { budget = 1; }
                    if (s.Length <= budget) { return s; }
                    truncated = true;
                    if (budget <= marker.Length) { return s.Substring(0, budget); }
                    var keep = budget - marker.Length; var head = keep / 2; var tail = keep - head;
                    return s.Substring(0, head) + marker + s.Substring(s.Length - tail, tail);
                }
                string fairJoin(System.Collections.Generic.List<string> parts, int budget) {
                    if (parts.Count == 0) { return ""; }
                    var share = Math.Max(1, budget / parts.Count); var joined = new System.Text.StringBuilder();
                    for (var i = 0; i < parts.Count; i++) { if (i > 0) { joined.Append("\n"); } joined.Append(sample(parts[i], share)); }
                    var result = joined.ToString(); if (result.Length > budget) { truncated = true; result = sample(result, budget); }
                    return result;
                }
                JObject root = null;
                try { var parsed = context.Request.Body.As<JToken>(preserveContent: true); root = parsed as JObject; if (root == null) { unscreenable = true; } } catch { unscreenable = true; }
                var truncateRaw = "{{content-safety-truncate-mode}}";
                var truncateMode = String.IsNullOrEmpty(truncateRaw) ? "newest" : truncateRaw.Trim().ToLowerInvariant();
                if (truncateMode != "newest") { truncateMode = "block"; }
                var analyzeParts = new System.Collections.Generic.List<string>();
                var userParts = new System.Collections.Generic.List<string>();
                var documentParts = new System.Collections.Generic.List<string>();
                JObject newestUser = null; var fabricated = false; var newestUserIndex = -1;
                if (!unscreenable) { var sysParts = new System.Collections.Generic.List<string>(); collectText(root["system"], sysParts); foreach (var p in sysParts) { analyzeParts.Add(p); } }
                if (!unscreenable) { var tools = root["tools"] as JArray; if (tools != null) { foreach (var toolToken in tools) { var toolObj = toolToken as JObject; if (toolObj != null && toolObj["description"] != null && toolObj["description"].Type == JTokenType.String) { addPart(documentParts, (string)toolObj["description"]); analyzeParts.Add((string)toolObj["description"]); } } } }
                if (!unscreenable) {
                    var messages = root["messages"] as JArray;
                    if (messages == null) { unscreenable = true; }
                    else {
                        for (var i = messages.Count - 1; i >= 0; i--) { var message = messages[i] as JObject; if (message == null) { unscreenable = true; break; } if (message["role"] != null && message["role"].Type == JTokenType.String && (string)message["role"] == "user") { newestUser = message; newestUserIndex = i; break; } }
                        if (!unscreenable && newestUserIndex > 0) { for (var h = 0; h < newestUserIndex; h++) { var historic = messages[h] as JObject; if (historic == null) { unscreenable = true; break; } if (historic["role"] != null && historic["role"].Type == JTokenType.String && (string)historic["role"] == "user") { fabricated = true; break; } } }
                        if (!unscreenable && newestUserIndex >= 0 && newestUserIndex + 1 < messages.Count) { var after = messages[newestUserIndex + 1] as JObject; if (after != null && after["role"] != null && after["role"].Type == JTokenType.String && (string)after["role"] == "assistant") { var prefill = new System.Collections.Generic.List<string>(); collectText(after["content"], prefill); foreach (var p in prefill) { userParts.Add(p); analyzeParts.Add(p); } } }
                    }
                }
                if (!unscreenable && newestUser != null) {
                    var userContentToken = newestUser["content"];
                    if (userContentToken != null) {
                        if (userContentToken.Type == JTokenType.String) { addPart(userParts, userContentToken.ToString()); analyzeParts.Add(userContentToken.ToString()); }
                        else if (userContentToken.Type == JTokenType.Array) {
                            foreach (var blockToken in (JArray)userContentToken) {
                                var block = blockToken as JObject; if (block == null) { unscreenable = true; break; }
                                if (block["type"] == null || block["type"].Type != JTokenType.String) { continue; }
                                var blockType = (string)block["type"];
                                if (blockType == "text") { if (block["text"] != null && block["text"].Type == JTokenType.String) { addPart(userParts, (string)block["text"]); analyzeParts.Add((string)block["text"]); } }
                                else if (blockType == "document") { var documentText = new System.Collections.Generic.List<string>(); collectText(new JArray(block), documentText); foreach (var p in documentText) { documentParts.Add(p); analyzeParts.Add(p); } }
                                else if (blockType == "tool_result") { var toolParts = new System.Collections.Generic.List<string>(); collectText(block["content"], toolParts); if (unscreenable) { break; } foreach (var p in toolParts) { documentParts.Add(p); analyzeParts.Add(p); } }
                            }
                        }
                        else { unscreenable = true; }
                    }
                }
                if (!unscreenable) {
                    var userRawLen = 0; foreach (var p in userParts) { userRawLen += p.Length; }
                    var analyzeRawLen = 0; foreach (var p in analyzeParts) { analyzeRawLen += p.Length; }
                    var docsRawLen = 0; foreach (var p in documentParts) { docsRawLen += p.Length; }
                    if (truncateMode == "block" && (userRawLen > 10000 || analyzeRawLen > 10000 || docsRawLen > 10000 || documentParts.Count > 5)) { unscreenable = true; truncated = true; }
                }
                if (unscreenable) { return new JObject(new JProperty("unscreenable", true), new JProperty("userPrompt", ""), new JProperty("documents", new JArray()), new JProperty("analyzeText", ""), new JProperty("truncated", truncated), new JProperty("emptyTextSlice", true), new JProperty("fabricatedHistoryLimit", false)).ToString(Newtonsoft.Json.Formatting.None); }
                var userPrompt = fairJoin(userParts, 10000);
                var documents = new JArray();
                if (documentParts.Count > 0) { if (documentParts.Count <= 5) { var share = Math.Max(1, 10000 / documentParts.Count); foreach (var p in documentParts) { documents.Add(sample(p, share)); } } else { var bucketCount = 5; var share = Math.Max(1, 10000 / bucketCount); for (var b = 0; b < bucketCount; b++) { var bucket = new System.Text.StringBuilder(); for (var i = b; i < documentParts.Count; i += bucketCount) { if (bucket.Length > 0) { bucket.Append("\n"); } bucket.Append(documentParts[i]); } documents.Add(sample(bucket.ToString(), share)); } truncated = true; } }
                var analyze = fairJoin(analyzeParts, 10000);
                return new JObject(new JProperty("unscreenable", false), new JProperty("userPrompt", userPrompt), new JProperty("documents", documents), new JProperty("analyzeText", analyze), new JProperty("truncated", truncated), new JProperty("emptyTextSlice", String.IsNullOrEmpty(analyze)), new JProperty("fabricatedHistoryLimit", fabricated)).ToString(Newtonsoft.Json.Formatting.None);
            }

@{
                        var threshold = (int)context.Variables["contentSafetyThreshold"];
