                        var analyze = context.Variables.ContainsKey("contentSafetyAnalyzeResponse") ? (IResponse)context.Variables["contentSafetyAnalyzeResponse"] : null;
                        var status = analyze != null ? analyze.StatusCode : (shield != null ? shield.StatusCode : 0);
                        var shieldNeeded = (bool)context.Variables["contentSafetyShieldNeeded"]; var shieldMissing = shieldNeeded && shield == null; var shieldFailed = shieldNeeded && shield != null && (shield.StatusCode < 200 || shield.StatusCode > 299);
                        if (shieldMissing || shieldFailed || analyze == null || analyze.StatusCode < 200 || analyze.StatusCode > 299) { return new JObject(new JProperty("decision", "unavailable"), new JProperty("blockedBy", "unavailable"), new JProperty("hateSeverity", 0), new JProperty("violenceSeverity", 0), new JProperty("selfHarmSeverity", 0), new JProperty("sexualSeverity", 0), new JProperty("promptShieldUserAttackDetected", false), new JProperty("promptShieldDocumentAttackDetected", false), new JProperty("contentSafetyStatusCode", status), new JProperty("contentSafetyErrorClass", shieldMissing || analyze == null ? "timeout" : "service_error")).ToString(Newtonsoft.Json.Formatting.None); }
                        try {
                            var sj = shieldNeeded ? shield.Body.As<JObject>(preserveContent: true) : new JObject(); var aj = analyze.Body.As<JObject>(preserveContent: true); var slice = JObject.Parse((string)context.Variables["contentSafetySlice"]);
                            if (shieldNeeded && !String.IsNullOrEmpty((string)slice["userPrompt"]) && (sj["userPromptAnalysis"] as JObject) == null) { throw new Exception("Malformed Prompt Shields response"); }
                            var userAttack = (bool?)sj["userPromptAnalysis"]?["attackDetected"] == true; var docAttack = false; var docs = sj["documentsAnalysis"] as JArray; var sentDocs = slice["documents"] as JArray; var sentDocCount = sentDocs == null ? 0 : sentDocs.Count; if (shieldNeeded && sentDocCount > 0 && (docs == null || docs.Count != sentDocCount)) { throw new Exception("Malformed Prompt Shields documents response"); } if (docs != null) { foreach (var d in docs) { if ((bool?)d["attackDetected"] == true) { docAttack = true; break; } } }
                            var hate = 0; var violence = 0; var selfHarm = 0; var sexual = 0; var cats = aj["categoriesAnalysis"] as JArray; if (cats == null) { throw new Exception("Malformed analyze response"); } foreach (var c in cats) { var cat = (string)c["category"]; var sev = (int?)c["severity"] ?? 0; if (cat == "Hate") { hate = sev; } else if (cat == "Violence") { violence = sev; } else if (cat == "SelfHarm") { selfHarm = sev; } else if (cat == "Sexual") { sexual = sev; } }
                            var blockedBy = ""; if (userAttack) { blockedBy = "prompt_shield_user"; } else if (docAttack) { blockedBy = "prompt_shield_document"; } else if (hate >= threshold || violence >= threshold || selfHarm >= threshold || sexual >= threshold) { blockedBy = "severity"; }
                            return new JObject(new JProperty("decision", blockedBy == "" ? "pass" : ((string)context.Variables["contentSafetyMode"] == "audit" ? "audit" : "block")), new JProperty("blockedBy", blockedBy == "" ? "none" : blockedBy), new JProperty("hateSeverity", hate), new JProperty("violenceSeverity", violence), new JProperty("selfHarmSeverity", selfHarm), new JProperty("sexualSeverity", sexual), new JProperty("promptShieldUserAttackDetected", userAttack), new JProperty("promptShieldDocumentAttackDetected", docAttack), new JProperty("contentSafetyStatusCode", status), new JProperty("contentSafetyErrorClass", "none")).ToString(Newtonsoft.Json.Formatting.None);
                        } catch { return new JObject(new JProperty("decision", "unavailable"), new JProperty("blockedBy", "unavailable"), new JProperty("hateSeverity", 0), new JProperty("violenceSeverity", 0), new JProperty("selfHarmSeverity", 0), new JProperty("sexualSeverity", 0), new JProperty("promptShieldUserAttackDetected", false), new JProperty("promptShieldDocumentAttackDetected", false), new JProperty("contentSafetyStatusCode", status), new JProperty("contentSafetyErrorClass", "malformed")).ToString(Newtonsoft.Json.Formatting.None); }
